# Bereshit (Genesis) 1:1–4:18 — English translation and commentary.
#
# Each entry: (verse_ref, lines, commentary). Lines are generated from the units in
# alignment.py; a line ends at sentence punctuation or after a long unit.
#
# Translated from the Hebrew witness, with the LXX (witness-lxx.json) as a second
# witness. No English rendering was consulted.

T = [
('1:1',
 ['At the start of it, Divinity began to cut:', 'the sky, and the ground.'],
 "Re'shit (רֵאשִׁית) is a construct: 'at the head of' or 'in the beginning of'. Read as a temporal clause, the verse becomes subordinate; the English keeps the main-clause reading, 'At the start of it, Divinity began to cut'. Bara' (בָּרָא) is used of Divinity in the Qal alone; its root is disputed, and 'cut' is one proposal, kept as the head term. 'Of it' is added to re'shit. The two objects, 'the sky' and 'the ground', are given as the English; 'erets is not adamah, and 'ground' is its head term. The particle 'et (אֵת) marks the object and is not rendered. LXX: 'en archē epoiēsen ho theos', 'in beginning made Divinity'; poiein replaces bara', and archē has no article."),
('1:2',
 ['The ground was a waste and a void.', 'Emptiness, nothing in it.', 'Dark lay on the face of the deep.', 'And the wind of Divinity, fluttering over the face of the waters.'],
 "Tohu and bohu (תֹהוּ וָבֹהוּ): 'waste, emptiness'; a stammering pair, kept as a pair. The English gives 'a waste and a void', then 'emptiness, nothing in it'. Tehom (תְּהוֹם), 'the deep', is compared by some to Tiamat; no etymology is established, and 'Deep' is capitalised in the English only as a force. Merachefet (מְרַחֶפֶת) is the participle of rachaf, used of a bird hovering over its young (Deut 32:11); the English 'fluttering over' keeps the participle without the simile. Ruach (רוּחַ) is wind, breath, or spirit; 'Wind' is chosen. LXX adds 'invisible' (aoratos) and 'unfurnished' (akataskeuastos), neither in the Hebrew, and renders the deep as 'abyss'."),
('1:3',
 ['Divinity said:', 'Let light be!', 'And there was light.'],
 "Yehi or (יְהִי אוֹר): 'let there be light'. The English has 'Let light be!' for the jussive and 'And there was light' for the narrative formula; the Hebrew has the plain jussive and the plain 'and it was'. LXX: 'let it become light' (genēthētō phōs), calmer."),
('1:4',
 ['Divinity saw the light: good.', 'Divinity split the light from the dark.'],
 "Badal (וַיַּבְדֵּל): 'separate, divide'; 'drove a gash' is the register's word for the same act. Tov (טוֹב) is 'good' as fitness, not virtue. LXX diechōrisen, 'separated'."),
('1:5',
 ['Divinity named the light Day.', 'The dark, Divinity named Night.', 'Evening came.', 'Morning came.', 'One day.'],
 "Yom echad (יוֹם אֶחָד): 'one day', not 'first day'. The count is cardinal here and ordinal from day two. The English keeps the plain nouns for 'erev and boqer, 'Evening came. Morning came.' LXX hēmera mia, the same cardinal."),
('1:6',
 ['Divinity said:', 'Let there be a hammered plate, in the middle of the waters, and let it split', 'water from water.'],
 "Raqia' (רָקִיעַ), from raqa', 'to beat out, spread thin'. 'Skin' and 'plate' keep the hammering; 'firmament' (Latin, 'support') drops it. Bein mayim lamayim is the ordinary idiom 'between water and water' (cf. Deut 17:8); nothing is odd about the lamed. LXX stereōma, 'firm thing'. LXX ends 1:6 with 'and it was so' (kai egeneto houtōs) and omits it at 1:7, where the Hebrew has it: the formula falls in a different place."),
('1:7',
 ['Divinity made the skin.', 'Divinity split the waters:', 'some under it, some over it.', 'So.'],
 "Vayya'as (וַיַּעַשׂ), 'made': the verb moves from bara' to 'asah, the plain 'make'. Wayehi-ken (וַֽיְהִי־כֵן), 'and it became so'; 'So. It held.' is a stretch of ken, 'thus'."),
('1:8',
 ['Divinity named the skin Sky.', 'Evening.', 'Morning.', 'The second day.'],
 "Shamayim (שָׁמַיִם), 'the heavens', plural in form. The folk etymology sham-mayim, 'there are waters', is not an established derivation; kept for the sound. Day two has no 'good' judgment in the Hebrew; the LXX supplies one ('and Divinity saw that it was good', witness-lxx.json)."),
('1:9',
 ['Divinity said: let the waters under the sky be gathered into one place,', 'and let the dry show itself.', 'So.'],
 "Yiqqavu (יִקָּווּ), from qavah: 'to wait, to gather into a line' and 'to hope' are often treated as separate roots; both are kept as readings. Tera'eh (תֵרָאֶה), 'let it be seen', becomes 'tear up, bare': the dry is torn into visibility. 'Beneath the heavens' (mittachat hashamayim) is not rendered: a loss. The LXX adds a report of execution: 'the water under heaven was gathered into its gatherings, and the dry appeared'."),
('1:10',
 ['Divinity named the dry Ground.', 'The gathering of the waters he named Seas.', 'Divinity saw: good.'],
 "Miqveh (מִקְוֵה), from qavah: 'gathering-place, pool'. The word for 'hope' (tiqvah) shares the root; 'waiting-hollow' keeps the verbs bound. Yamim (יַמִּים), 'seas', plural. LXX thalassas."),
('1:11',
 ['Divinity said: let the ground sprout a sprouting— plants spitting seed,', 'fruit tree making fruit after its kind, seed in its own body, on the ground.', 'So.'],
 "Tadshe' (תַּדְשֵׁא), from dasha': a cognate accusative, 'green a greening'. The verb and its noun deshe' are one word; 'green-burst a greening' keeps the compression. Lemino (לְמִינוֹ): 'after its kind' (min, species). LXX blastēsatō, 'let it sprout', and botanē chortou, 'herb of grass': the Greek keeps both nouns; what is lost is the verb-noun compression of dasha'."),
('1:12',
 ['The ground heaved and pushed up a greening:', 'plants spitting seed after its kind, fruit tree making fruit, seed in its body, after its kind.', 'Divinity saw: good.'],
 "Wattotse' (וַתּוֹצֵא): the ground, feminine, brings forth. 'Heaved' is the bodily verb for the agent. LXX exēnenken, 'brought forth'."),
('1:13',
 ['Evening.', 'Morning.', 'The third day.'],
 'The day-count is a frame: the formula repeats. Compare 1:5.'),
('1:14',
 ['Divinity said: let there be lamps in the hammered sky, splitting day from night.', 'Let them be marks and meeting-times, days and years.'],
 "Me'orot (מְאֹרֹת), from 'or (light, fire): 'fire-holders'. The text names neither sun nor moon here. Lemo'adim (לְמוֹעֲדִים), 'for appointed times', from ya'ad, 'to meet at an appointed place': 'meeting-hours' stretches it. Shanim (שָׁנִים) is the first 'year' (shanah; a 'repeat' root is proposed, not settled). LXX lists nouns: phōstēres, sēmeia, kairous, hēmeras, eniautous. LXX adds eis phausin tēs gēs, 'for giving light to the earth', a plus with no Hebrew counterpart in the formula. LXX adds 'to give light to the earth' (eis phausin tes ges), which has no Hebrew counterpart."),
('1:15',
 ['Let them be lamps in the hammered sky, to pour light on the ground.', 'So.'],
 "Lehe'ir (לְהָאִיר), the causative of 'or: 'to pour light'. The verb ties the lamps back to 1:3."),
('1:16',
 ['Divinity made the two great lamps:', 'the greater to rule the day, the lesser to rule the night, and the stars.'],
 "Memshelet (מֶמְשֶׁלֶת), 'dominion', from mashal. Mashal 'rule' and mashal 'proverb' are usually treated as homonyms; the pun is the English's, not established. The text names neither sun (shemesh) nor moon (yarach); commentators have remarked this. LXX keeps the two-lamp structure."),
('1:17',
 ['Divinity gave them a place in the hammered sky to pour light on the ground.'],
 "Wayyiten (וַיִּתֵּן), 'gave, set'. 'Hung' is the register: the lamps are placed like objects."),
('1:18',
 ['to rule the day and the night, to split the light from the dark.', 'Divinity saw: good.'],
 "Lim-shol (לִמְשֹׁל), 'to rule', the root of mashal. Lehavdil (לְהַבְדִּיל) repeats the badal of 1:4: the seam is cut twice."),
('1:19',
 ['Evening.', 'Morning.', 'The fourth day.'],
 "Rebi'i (רְבִיעִי), the ordinal."),
('1:20',
 ['Divinity said:', 'let the waters swarm with a swarm of breathing things;', 'and let fliers flutter over the ground, across the face of the hammered sky.'],
 "Yishretzu (יִשְׁרְצוּ), from sheretz: small things that teem and crawl; 'swarm' is the English. Nefesh chayah (נֶפֶשׁ חַיָּה), 'living breath, living creature'. Nefesh is breath, throat, self; LXX psychē zōsa, 'living soul', puts the soul into the animal. Ye'opef (יְעוֹפֵף), a doubled verb of flying, is 'flutter'. Raqia' is rendered 'the hammered sky' here; its head term is open (see lexicon.md). LXX adds kai egeneto houtōs, 'and it was so', a formula plus not in the Hebrew at this point."),
('1:21',
 ['Divinity cut the great serpents, the tanninim, and every living breath that crawls,', 'which the waters swarmed with, after their kinds, and every winged bird, after its kind.', 'Divinity saw: good.'],
 "Tanninim (תַּנִּינִם), 'sea-serpents, great monsters': the creature-word of older chaos-myths (Ps 74:13). The verb is bara' again: the old monsters are made, not slain. Commentators have often noted the absence of combat."),
('1:22',
 ['Divinity blessed them:', 'Bear fruit!', 'Grow many!', 'Fill the waters in the seas!', 'Let the fliers breed on the ground.'],
 "Wayevarekh (וַיְבָרֶךְ): 'blessed'. The root barak is often linked to 'knee' (berekh), a link debated. Peru (פְּרוּ), from parah: 'break out, bear fruit'. Rivu (רְבוּ), from rabah: 'become a crowd'. LXX gives auxanesthe, plēthynesthe, plērōsate: two verbs of growth and 'fill'; 'burst' is lost there."),
('1:23',
 ['Evening.', 'Morning.', 'The fifth day.'],
 'Hamishi (חֲמִישִׁי), the ordinal.'),
('1:24',
 ['Divinity said:', 'let the ground bring out breathing things after their kind:', 'cattle, crawlers, beasts of the ground, each after its kind.', 'So.'],
 "Totse' (תּוֹצֵא): 'bring out'. Chayto 'erets (חַיְתוֹ־אֶרֶץ), 'its beast of the earth' (the construct of 1:24, not the form of 1:25). The English lists 'cattle, crawlers, beasts of the ground' for behemah, remesh and chayat ha'arets. Remesh (רֶמֶשׂ), 'crawler'."),
('1:25',
 ['Divinity made the beast of the ground after its kind, the cattle after its kind,', 'every crawler of the red earth after its kind.', 'Divinity saw:', 'good.'],
 "Adamah (אֲדָמָה) is ground, soil; 'red' is a gloss from the colour of the soil, not an established sense; the root of adam (human) is the same family. 'The red' keeps that family alive and sets up 2:7."),
('1:26',
 ['Divinity said:', 'let us make a human, an earthling, in our image,', 'as our likeness.', 'Let them tread down the fish of the sea, the bird of the sky,', 'the cattle, the whole ground, every living thing that crawls on the ground.'],
 "Na'aseh (נַעֲשֶׂה), 'let us make': first person plural. Readings include a divine council, a royal 'we', and address to heavenly beings; none is secure. 'A human' renders 'adam, which has no article here; 'an earthling' stretches adamah (2:7) toward the ground it comes from. Tselem (צֶלֶם), 'image': from a root some link to 'shade' or 'cut'. Demut (דְּמוּת), 'likeness'. Yirdu (יִרְדּוּ), from radah: 'tread down' is the English; the Hebrew also carries 'rule'. LXX poiēsōmen, 'let us make', with hēmeteran, 'ours'."),
('1:27',
 ['Divinity cut the human in his image— in the image of Divinity', 'Divinity cut him— male and female Divinity cut them.'],
 "Bara' (בָּרָא) occurs three times here; 'cut' keeps the striking; the head term is 'cut' (lexicon.md). LXX epoiēsen, 'made', three times: the threefold verb is flattened. Tselem recurs. The pronoun 'his' can refer to Divinity or to the human; the Hebrew holds both."),
('1:28',
 ['Divinity blessed them.', 'Divinity said:', 'Bear fruit, grow many, fill the ground;', 'trample it; tread down the fish of the sea, the bird of the sky, every living thing that crawls on the ground.'],
 "Kivshuha (כִּבְשֻׁהָ), from kavash: 'to subdue'. Kavas, 'to press and beat cloth', is a different root from kavash: the washing-pit is the English's addition, not a Hebrew sense. LXX katakyrieusate, 'lord it over', is a legal verb. Radu (רְדוּ) is the verb of 1:26."),
('1:29',
 ['Divinity said:', 'Look— I have given you every seed-spitting plant over the whole face of the ground,', 'and every fruit tree that holds seed-fruit in itself.', 'For you: to eat.'],
 "Hinneh natati (הִנֵּה נָתַתִּי), 'look, I have given': the perfect with hinneh states a present fact. Lakhem (לָכֶם), 'to you'. The animals' food is given in 1:30. LXX idou dedōka, the same 'look'."),
('1:30',
 ['And for every beast of the ground, every bird of the sky, everything that crawls on the ground that has living breath in it:', 'all the green plants, to eat.', 'So.'],
 "Yereq (יֶרֶק), 'green'. Every animal is fed on green."),
('1:31',
 ['Divinity saw all he had made— and look:', 'very good.', 'Evening. Morning:', 'the sixth day.'],
 "Tov me'od (טוֹב מְאֹד), 'good, exceedingly'. LXX kala lian, 'very beautiful'. The LXX's kalos is a wider register of beauty."),
('2:1',
 ['Sky and ground were finished, and all their army.'],
 "Vayekhullu (וַיְכֻלּוּ), 'were finished, completed'. Tzeva'am (צְבָאָם), 'their host, army': the stars and the whole mustered order. LXX pas ho kosmos autōn, 'all their order': 'cosmos' for 'host'."),
('2:2',
 ['Divinity finished on the seventh day the work he had made;', 'and on the seventh day he quit, dropped all the work he had made.'],
 "Witness variant. The Hebrew reads 'the seventh day' for the completion; the LXX reads 'the sixth day' (en tē hēmera tē hektē) here. Shavat (שָׁבַת), 'cease', is the root from which 'sabbath' derives; the verse does not yet name a day of rest as an institution. 'Quit' is the register's word for ceasing labour. LXX reads 'in the sixth day' (en te hemera te hekte) for the completion, where the Hebrew has 'on the seventh day'. The seventh-day rest is kept in the LXX; the variant is recorded, not adopted."),
('2:3',
 ['Divinity blessed the seventh day, and set it apart,', 'because on it he quit all the work Divinity cut to make.'],
 "Vayevarekh (וַיְבָרֶךְ), 'blessed'; vayqaddesh (וַיְקַדֵּשׁ), 'set apart', from qadosh. The 'cut away' gloss is speculative and is not used. The English gives 'blessed' once, for the seventh day, and 'set it apart'. Bara' with the infinitive la'asot (לַעֲשׂוֹת) is a doubled verb. LXX hōn ērxato ho theos poiēsai, 'which Divinity began to make': the LXX reads 'began', rendering the bara' + la'asot idiom; weak support for the temporal reading of 1:1."),
('2:4',
 ['These are the births— of sky and ground, when they were cut, in the day the Lord Divinity made', 'ground and sky.'],
 "Toledot (תּוֹלְדוֹת): 'births, generations', from yalad, 'to bear'. The English 'births' is the head term. LXX hautē hē biblos geneseōs, 'this is the book of origin': the source of the Greek title Genesis. The order inverts 1:1: a chiasm. 'the Lord' is left as the Name, unpronounced in the tradition. LXX has ho theos alone, without kyrios, where the Hebrew has the Lord Divinity: the Name is not rendered in the Greek. LXX has no 'Lord' (kyrios) here; it reads 'God' (ho theos) for YHWH Elohim, and 'book of the origin' for toledot."),
('2:5',
 ['No bush of the field yet on the ground, no plant of the field, not yet sprouted.', 'for the Lord Divinity had not rained on the ground, and no human to work the red earth.'],
 "Siach (שִׂיחַ), 'shrub'; a separate siach, 'meditation, talk', is probably a homonym (Ps 77:13 Hebrew numbering; 77:12 English). Sadeh (שָׂדֶה), 'open field, wild land'. Le-ovod (לַעֲבֹד), 'to work, to serve'. LXX has ho theos alone for the Lord Divinity here, as at 2:4."),
('2:6',
 ['A seep welled up out of the ground and soaked the whole face of the red earth.'],
 "Ed (אֵד), 'mist, flow, spring': the Hebrew can be a vapour or an underground seep; 'seep' keeps the second. LXX pēgē, 'spring'."),
('2:7',
 ['The Lord Divinity potted the human out of the dust of the red earth,', 'and blew into his nostrils the breath of lives;', 'and the human became a living breath.'],
 "Yatzar (יָצַר): 'to shape, mould' as a potter does: 'potted'. Afar (עָפָר), 'dust'. Appav (אַפָּיו), 'his nostrils'; the same word is used of anger (aph). Nefesh chayah is 'living breath' for the animals in 1:20–21; here 'living throat'. LXX eis psychēn zōsan, 'living soul'. LXX renders the nostrils as eis to prosōpon, 'into the face', not 'into the nostrils'. LXX has ho theos alone for the Lord Divinity here (kyrios is dropped), as at 2:4."),
('2:8',
 ['The Lord Divinity planted a garden in Eden, to the east, and set there the human he had potted.'],
 "Eden (עֵדֶן): 'delight, pleasure'; etymology disputed (a Sumerian loan edin, 'steppe', is proposed). Miqqedem (מִקֶּדֶם): 'from before, of old' or 'eastward'; the English keeps the readings together. LXX kata anatolas, 'to the east', chooses one. Gan (גַּן), 'enclosure, garden'."),
('2:9',
 ['From the red earth he made sprout every tree to be coveted to the eye,', 'and good to eat;', 'the tree of lives in the middle of the garden, and the tree of knowing good and harm.'],
 "Nekhmad (נֶחְמָד): 'desirable, coveted' (cf. 3:6). Chayyim (חַיִּים): 'lives', plural. Da'at (דַּעַת), 'knowing'; yada' is the verb of intimate knowledge (4:1). Tov va-ra' (טוֹב וָרָע): 'good and harm'; ra' carries ruin as well as evil. LXX adds 'known' (gnōston). LXX has ho theos alone for the Lord Divinity here, as at 2:4."),
('2:10',
 ['A river came out of Eden to water the garden;', 'from there it branched and became four heads.'],
 "Ro'shim (רָאשִׁים): 'heads, sources, beginnings'. Ro'sh (head) is the root of re'shit (1:1). LXX archas, 'beginnings', keeps the echo of archē."),
('2:11',
 ['The first: Pishon.', 'It goes round all the land of Havilah, where the gold is.'],
 "Havilah (חֲוִילָה), a place name; its root may be chul, 'to writhe, to bring forth in labour'. The English keeps only the name; the echo is not carried. Zahav (זָהָב), 'gold'. 'Goes round' renders sovev (participle of sabab, 'go round')."),
('2:12',
 ['The gold of that land is good.', 'There is bdolach, and the stone shoham.'],
 "Bedolach (בְּדֹלַח) and shoham (שֹׁהַם) are of uncertain identity. LXX gives anthrax (coal, carbuncle) and 'the green stone'."),
('2:13',
 ['The second: Gihon.', 'It goes round all the land of Kush.'],
 "Gihon (גִּיחוֹן), possibly from gihah, 'to gush forth' (a folk link, not established): the name hears its own action. Kush (כּוּשׁ) is a southern land, usually placed in Nubia or Ethiopia. LXX Aithiopia."),
('2:14',
 ['The third: Hiddekel, running east of Ashur.', 'The fourth: Perat.'],
 "Hiddekel (חִדֶּקֶל) is the Tigris; Perat (פְּרָת) the Euphrates. Kidmat (קִדְמַת), 'east of, before', is the word of miqqedem (2:8). LXX katenanti Assyrion, 'opposite the Assyrians'."),
('2:15',
 ['The Lord Divinity took the human and set him in the garden in Eden—', 'to serve it, to guard it.'],
 "La'avdah (לַעֲבְדָהּ), 'to serve, work'; lishmrah (לִשְׁמְרָהּ), 'to keep, guard'. 'Serve' is the verb of slavery as well as labour; LXX ergazesthai and phylassein drop the servitude. LXX adds hon eplasen, 'which he had formed', a relative plus the Hebrew does not have."),
('2:16',
 ['The Lord Divinity charged the human:', 'From every tree of the garden you may eat and eat.'],
 "The infinitive absolute: akhol tokhel (אָכֹל תֹּאכֵל), 'eating, eat'. The doubling is emphatic."),
('2:17',
 ['But from the tree of knowing good and harm, do not eat.', 'On the day you eat from it, dying, you will die.'],
 "Mot tamut (מוֹת תָּמוּת), 'dying, you shall die': the infinitive absolute again. 'On the day' (be-yom) can name an interval; the narrative records no death that day. LXX thanatō apothaneisthe keeps the doubling. LXX uses plural forms (phagesthe, 'you all'), while the Hebrew is singular: a number shift in the prohibition. LXX has the plural 'you shall eat' (phagesthe) for the singular Hebrew, and 'die, you shall die' as 'dying you shall die' (thanato(i) apothaneisthe)."),
('2:18',
 ['The Lord Divinity said: not good, the human alone.', 'I will make him a help, a face set across from him.'],
 "Ezer (עֵזֶר), 'help'. The word is used of Divinity (Ps 33:20) and implies no inferiority. Kenegdo (כְּנֶגְדּוֹ), 'opposite him': a mirror-face. LXX boēthon kat' auton, 'a helper like him'. LXX 2:18 reads poiēsōmen ('let us make') for the Hebrew 'eeseh ('I will make'). LXX has 'let us make' (poiesomen) for the Hebrew 'I will make' (e'eseh); the first person plural is shared with 1:26's 'let us make'."),
('2:19',
 ['From the red earth, the Lord Divinity potted every beast of the field', 'and every bird of the sky, and brought them to the human to see what he would call them.', 'Whatever the human called each breathing thing, that was its name.'],
 "Yatzar again: the verb of 2:7. Mah-yiqra-lo (מַה־יִּקְרָא־לוֹ), 'what he would call them'. Shemo (שְׁמוֹ), 'its name'. LXX eplasen, 'formed'. LXX has ho theos alone for the Lord Divinity here, as at 2:4."),
('2:20',
 ['The human called names:', 'to all the cattle, to the bird of the sky, to every beast of the field.', 'But for the human he found no help facing him.'],
 "Lo matsa (לֹא־מָצָא), 'did not find'. LXX ouch heurethē boēthos homoios, 'no similar helper was found'."),
('2:21',
 ['The Lord Divinity threw a heavy sleep on the human, and he slept.', 'Divinity took one of his ribs and shut the meat over the place.'],
 "Tardemah (תַּרְדֵּמָה): deep sleep, trance (cf. 15:12). Tsela' (צֵלָע): 'side, rib'. Vayisgor (וַיִּסְגֹּר): 'shut'. LXX ekstasin, 'ecstasy'. LXX has ho theos alone for the Lord Divinity here, as at 2:4."),
('2:22',
 ['The Lord Divinity built the side he had taken from the human into a woman,', 'and brought her to the human.'],
 "Vayiven (וַיִּבֶן): 'built', the verb of building a house (bayit) and a family. The rib is built, not bred. LXX ōkodomēsen, 'built'."),
('2:23',
 ['The human said: This time—at last— bone out of my bones, meat out of my meat!', 'This one shall be called Ishah, for from Ish she was taken.'],
 "Zot ha-pa'am (זֹאת הַפַּעַם): 'this time', idiomatically 'at last'. The English keeps 'at last' and does not add an exclamation. 'Bones' is the plural of 'etzem. Ishah (אִשָּׁה), 'woman'; Ish (אִישׁ), 'man'. The pun works in Hebrew and fails in English, so the transliteration stays. LXX gynē and andros lose it."),
('2:24',
 ['Therefore: a man leaves father and mother, clings to his woman;', 'and they become one meat.'],
 "Ya'azov (יַעֲזָב), 'leaves, forsakes'. Davaq (דָּבַק), 'cling, weld', to cling, stick (not a settled mortar sense): 'glues' keeps the material sense. 'Therefore' (al-ken) marks the narrator stepping out of the story. LXX adds hoi duo, 'the two'. LXX adds 'the two' (hoi duo) before 'shall be into one flesh'."),
('2:25',
 ['Both bare, the human and his woman, and no shame.'],
 "Arumim (עֲרוּמִּים), 'naked, bare'. Arum (עָרוּם), in 3:1, means 'crafty, shrewd': the same consonants carry both senses."),
('3:1',
 ['The serpent was shrewder than any beast of the field the Lord Divinity had made.', 'It said to the woman:', 'Did Divinity really say, you shall not eat from any tree of the garden?'],
 "Nachash (נָחָשׁ), 'serpent'. The word sits near nechoshet (bronze) and nachash (divination). 'The serpent' is for the sibilance. Af ki (אַף כִּי), 'really?'. LXX asks 'why, that Divinity said' (ti hoti eipen)."),
('3:2',
 ['The woman said to the serpent:', 'From the fruit of the trees of the garden, we eat.'],
 "The woman's answer omits the one tree that 3:3 names. Nochel (נֹאכֵל): 'we eat'."),
('3:3',
 ['But from the fruit of the tree in the middle of the garden, Divinity said:', 'do not eat from it, do not touch it, or you will die.'],
 "'Do not touch it' is not in 2:17. The woman adds a prohibition. Pen-tmutun (פֶּן־תְּמֻתוּן): 'lest you become dead'. The LXX has the same addition (mēde hapsēsthe), so the addition is already in the Hebrew narrative as the woman's own speech; the Greek agrees."),
('3:4',
 ['The serpent said to the woman:', 'You will not die, not die.'],
 "Lo mot temutun (לֹא־מוֹת תְּמֻתוּן): 'not death, you shall die-not'. The serpent reverses the infinitive of 2:17. LXX ou thanatō apothaneisthe."),
('3:5',
 ['For Divinity knows:', 'the day you eat from it, your eyes will split open, and you will be like the divine ones,', 'knowing good and harm.'],
 "Yodea (יֹדֵעַ), 'knows'. Niftechu (נִפְקְחוּ), 'opened', from paqach, 'open (the eyes)'. Kelohim (כֵּאלֹהִים): 'like gods' or 'like Divinity'; 'Gods' capitalised. LXX hōs theoi, 'like gods'."),
('3:6',
 ['The woman saw:', 'the tree good to eat, a hunger for the eyes, a tree to be coveted for insight.', 'She took from its fruit and ate.', 'She gave to her man with her, and he ate.'],
 "Ta'avah (תַּאֲוָה): 'craving, desire'. Lehaskil (לְהַשְׂכִּיל): 'to make wise, to see through'. The man is 'with her' (immah): the text does not place him. LXX aresta tois ophthalmois, 'pleasing to the eyes': the craving is softened."),
('3:7',
 ['Both their eyes split open, and they knew they were bare;', 'they sewed fig-leaves and made loin-belts.'],
 "Vayyidu (וַיֵּדְעוּ), 'they knew': the knowing of 2:9 plays out. Tafar (תָּפַר), 'to sew, stitch'. Hagorot (חֲגֹרֹת), 'belts, girdles'. LXX perizōmata, 'wraps'."),
('3:8',
 ['They heard the voice of the Lord Divinity pacing in the garden at the wind of the day;', 'the human and his woman hid from the face of the Lord Divinity', 'among the trees of the garden.'],
 "Mithalekh (מִתְהַלֵּךְ): 'walking back and forth, pacing'. Ruach ha-yom (רוּחַ הַיּוֹם): 'wind of the day'; 'cool of the day' is an English gloss. LXX to deilinon, 'the afternoon'."),
('3:9',
 ['The Lord Divinity called to the human and said to him:', 'Where are you?'],
 "Ayyekka (אַיֶּכָּה): 'where?', a rare form of ayeh. The question is Divinity's, put to one who hides. LXX pou ei. LXX has the vocative Adam, 'Adam, where are you?', where the Hebrew has the plain 'where'."),
('3:10',
 ['He said: I heard your voice in the garden.', 'I shook, for I am bare, and I hid.'],
 "Ira (אִירָא): 'fear, shudder'. The root carries awe as well as dread. LXX adds peripatountos, 'walking', to the voice in the garden: the Hebrew has the voice alone."),
('3:11',
 ['Divinity said: Who told you you were bare?', 'Did you eat from the tree I charged you not to eat from?'],
 "Ha-min (הֲמִן): interrogative 'from'. Tsiviti (צִוִּיתִיךָ): 'I charged you'. LXX tis anēngeilen soi, 'who announced to you'. LXX adds toutou monou, 'of this one alone', to the prohibition, a plus of emphasis."),
('3:12',
 ['The human said: The woman you gave to be with me— she gave me from the tree, and I ate.'],
 "Immadi (עִמָּדִי), 'with me'. The man puts the blame on the gift."),
('3:13',
 ['The Lord Divinity said to the woman: What is this you have done?', 'The woman said: The serpent snared me, and I ate.'],
 "Hishi'ani (הִשִּׁיאַנִי): from nasha', 'to deceive, to beguile' (nasha' II; the 'forget' sense belongs to nasha' I). 'Snared' is the English's image. LXX ēpatēsen, 'deceived'."),
('3:14',
 ['The Lord Divinity said to the serpent: Because you did this— cursed are you, out of all the cattle,', 'and out of every beast of the field.', 'On your gut you will go, and dust you will eat all the days of your life.'],
 "Gechon (גְּחוֹן), 'belly, underside'. Afar (עָפָר): 'dust'. LXX gēn, 'earth', for dust, and 'chest and belly': the Greek adds the chest."),
('3:15',
 ['Hatred I will set between you and the woman, between your seed and her seed:', 'he—it—will snap at your head;', 'you will snap at its heel.'],
 "Eivah (אֵיבָה), 'enmity, hatred'; 'hatred' is the English here. Hu (הוּא): 'he, it', masculine. Zera' (זֶרַע), 'seed', is collective. Yeshufka (יְשׁוּפְךָ): from shuf, 'crush, bruise'. The English uses 'snap at' for both clauses (one verb for one root). LXX autos tērēsei, 'he will watch': 'crush' becomes 'guard'. Read as messianic prophecy in later tradition; the Hebrew names no single victor."),
('3:16',
 ['To the woman he said: I will multiply, multiply your pain and your conceiving.', 'In pain you will bear children.', 'Toward your man your craving, and he will rule you.'],
 "Itstsavon (עִצָּבוֹן), 'pain, toil'. Heronek (הֵרֹנֵךְ): 'your conception'. 'Groaning' follows the LXX's stenagmos, a witness reading, not the Hebrew. Teshuqah (תְּשׁוּקָה): 'craving, drive'; the same word is sin's craving in 4:7. Yimshol (יִמְשֹׁל): 'rule'. LXX apostrophē, 'turning back'."),
('3:17',
 ["To the human he said: Because you listened to your woman's voice", "and ate from the tree I charged you about—'do not eat from it'—", 'cursed is the red earth because of you.', 'In pain you will eat from it all the days of your life.'],
 "Ha-adamah (הָאֲדָמָה), 'the red earth ground'. Be-itstsavon (בְּעִצָּבוֹן): 'in pain', the noun of 3:16. LXX reads 'in the works' (en tois ergois) for 'for your sake' (a variant reading, not an addition). LXX adds toutou monou here too, the same emphatic plus as 3:11. LXX reads 'in your works' (en tois ergois sou) for the Hebrew 'because of you' (ba'avurekha)."),
('3:18',
 ['Thorn and thistle it will sprout for you;', 'you will eat the plant of the field.'],
 "Qos (קוֹץ): 'thorn'. Dardar (דַּרְדַּר): 'thistle'. LXX akanthas kai tribolous, 'thorns and caltrops'."),
('3:19',
 ['In the sweat of your nose you will eat bread until you return to the red earth—for from it you were taken.', 'Dust you are, and to dust you turn back.'],
 "Appayim (אַפַּיִם): 'face, nostrils, anger', the word of 2:7. Lukkachta (לֻקָּחְתָּ): 'you were taken'. LXX en hidrōti, 'in sweat'."),
('3:20',
 ['The human named his woman Chavah—Living— for she became mother of all the living.'],
 "Chavah (חַוָּה), 'Eve': the text itself links it to chayah, 'to live', as wordplay; the derivation is the text's, not a settled etymology. LXX Zōē, 'life'."),
('3:21',
 ['The Lord Divinity made for the human and his woman hide-coats, and dressed them.'],
 "Ketonot or (כָּתְנוֹת עוֹר): 'skin-tunics'. LXX chitōnas dermatinous, 'leather tunics'."),
('3:22',
 ['The Lord Divinity said:', 'Look— the human has become like one of us, knowing good and harm.', 'Now lest he reach out his hand, take also from the tree of lives,', 'eat, and live—forever.'],
 "Ke-echad mi-mennu (כְּאַחַד מִמֶּנּוּ): 'like one of us' or 'of it'. The 'us' is plural. 'Forever' (le-olam) names the boundary death keeps. LXX hōs heis ex hēmōn, 'as one of us'. LXX has ho theos alone for the Lord Divinity here, as at 2:4."),
('3:23',
 ['The Lord Divinity sent him out from the garden in Eden, to serve the red earth from which he was taken.'],
 "Vayshalhehu (וַיְשַׁלְּחֵהוּ): 'sent him away'. La-avod (לַעֲבֹד): 'to serve, work'."),
('3:24',
 ['He drove the human out.', 'At the east of the garden in Eden he set the cherubim and the flame of the turning blade, to guard the road to the tree of lives.'],
 "Vayegaresh (וַיְגָרֶשׁ): 'drove out'. Garash is 'drive out'; the divorce sense belongs to the participle gerushah (Lev 21:7; 22:13). Kerubim (כְּרֻבִים): winged guardians. Hammitpakhet (הַמִּתְהַפֶּכֶת): 'turning, reversing itself'. LXX strephomenēn, 'turning'. LXX reads 'and he settled him (Adam) opposite the garden of delight' (katōikisen): the human is the object of the settling, a different sense from the Hebrew's 'he set the cherubim'. LXX renders Eden as 'the paradise of delight' (tes truphes), has no word for 'east', and adds the cherubim (cheroubim) stationed with the flaming revolving sword to keep the way."),
('4:1',
 ['Now the human knew Chavah his woman;', 'she conceived and bore Qayin, and said:', 'I have gotten a man with the Lord.'],
 "Yada' (יָדַע): 'knew', the verb of knowing and of intimacy. Qanah (קָנִיתִי): 'I have gotten'; the root also means 'to create' (Gen 14:19). Qayin (קַיִן): 'spear, smith', a scholarly proposal; the text's own wordplay is qaniti. The 'et' of 'et the Lord' is ambiguous: 'with the Lord' or 'the Lord' in apposition; the English keeps only the apposition reading. LXX reads dia tou theou, 'through Divinity', for the Hebrew 'et the Lord: a witness reading that makes the 'et a means, not an apposition."),
('4:2',
 ['She bore again: his brother Hevel.', 'Hevel, herder of flocks.', 'Qayin, worker of the red earth.'],
 "Hevel (הֶבֶל): 'breath, vapour, vanity', the word of Ecclesiastes. Oved adamah (עֹבֵד אֲדָמָה): 'worker of the ground', from the verb 'serve' (2:15). LXX Abel: a transliteration."),
('4:3',
 ['When the days ran out, Qayin brought from the fruit of the red earth a gift to the Lord.'],
 "Miqqetz (מִקֵּץ): 'from the end, at the cut-off'. Minchah (מִנְחָה): 'gift, offering'. LXX meth' hēmeras, 'after days': the Greek drops 'end'."),
('4:4',
 ['And Hevel too brought from the firstborn of his flock, from their fat,', 'and the Lord looked on Hevel and on his gift.'],
 "Bekhorot (בְּכֹרוֹת), 'firstborn'. Chelbehen (חֶלְבֵהֶן): 'their fat', the richest portion. Vayisha' (וַיִּשַׁע): 'looked, regarded'. LXX epeiden, 'looked upon'."),
('4:5',
 ['But to Qayin and his gift he did not look.', 'Qayin burned, burned hard, and his face fell.'],
 "Vayyichar (וַיִּחַר): 'burned, grew hot', of anger. Vayyippelu panav (וַיִּפְּלוּ פָּנָיו): 'his face fell'. LXX sun-epesen tō prosōpō, 'fell together upon his face'. LXX reads elypēsen ('grieved') at 4:5 and perilypos at 4:6, where the Hebrew has the burning anger of charah: a sense shift, recorded here."),
('4:6',
 ['The Lord said to Qayin:', 'Why do you burn?', 'Why has your face fallen?'],
 "Lamah (לָמָּה), 'why'. The first divine speech to a human in the Cain story; a question, not yet a judgment. The LXX has kyrios ho theos ('The Lord God') for the Hebrew YHWH alone here; the plus is recorded."),
('4:7',
 ['If you do well, is there not a lifting?', 'If you do not do well, at the door a sin crouches— its craving is for you; but you will rule it.'],
 "Se'et (שְׂאֵת): 'lifting'. The idiom se'et panim is not in this verse; 'of the face' in the English is an addition. Lapetach (לַפֶּתַח): 'at the door'. Chatta't (חַטָּאת): 'sin, sin-offering'. Rovets (רֹבֵץ): 'crouching', as a beast lies in wait. Teshuqah: the craving of 3:16, now the sin's. Timshol (תִּמְשׁל): 'you will rule'. LXX hēsychason, 'be still', and 'divide rightly' (orthōs dielēs), a cultic gloss the Hebrew does not give."),
('4:8',
 ['Qayin spoke to Hevel his brother— when they were in the field,', 'Qayin rose against Hevel his brother and killed him.'],
 "The Hebrew records Qayin's words with no content: the dash in the English marks the gap; the witness has no gap marker. The LXX fills the gap: 'let us go out into the field'. Vayyaqom (וַיָּקָם): 'rose up', 'reared'. Vayahargehu (וַיַּהַרְגֵהוּ): harag, a violent slaying. LXX adds 'let us go out into the field' (dielthomen eis to pedion) and then 'and it happened, while they were in the field'; the Hebrew has no speech after 'said'."),
('4:9',
 ['The Lord said to Qayin: Where is Hevel your brother?', 'He said: I do not know.', 'Do I guard my brother?'],
 "Shomer (שֹׁמֵר): 'keeper, guard', from shamar. The same verb in 2:15 sets the human to keep the garden. LXX phylax, 'guard'."),
('4:10',
 ['He said: What have you done?', "A voice—your brother's bloods— cries to me from the red earth."],
 "Demei (דְּמֵי): 'bloods', the plural of blood, used for violent death. LXX phōnē haimatos, 'voice of blood', singular."),
('4:11',
 ["Now: cursed are you from the red earth, which gaped its mouth to take your brother's bloods from your hand."],
 "Patzta (פָּצְתָה): 'opened, gaped'. The earth is given a mouth (peh). LXX echanen, 'gaped'."),
('4:12',
 ['When you work the red earth, it will no more give you its strength.', 'A stumbler, a roamer, you will be on the ground.'],
 "Na' va-nad (נָע וָנָד): 'staggering and wandering'. Ko'ach (כֹּחַ): 'strength'. LXX stenōn kai tremōn, 'groaning and trembling'."),
('4:13',
 ['Qayin said to the Lord: My guilt is heavier than I can lift.'],
 "Avon (עָוֹן): 'guilt, iniquity, punishment'. Minnesso (מִנְּשֹׂא): 'from lifting'; nasa' both carries and forgives. LXX aitia, 'charge, cause'. LXX reads tou aphethēnai me, 'to be forgiven', so the Greek takes the forgiveness sense as the main one."),
('4:14',
 ['Look—you drive me out today from the face of the red earth.', 'I will hide from your face;', 'I will be a stumbler and a roamer on the ground, and whoever finds me will kill me.'],
 "Garashta (גֵּרַשְׁתָּ): 'you drove out', garash again (see 3:24). Yahargeni (יַהַרְגֵנִי): 'will kill me', harag again."),
('4:15',
 ['The Lord said to him: Therefore— whoever kills Qayin will be paid back sevenfold.', 'The Lord set a sign for Qayin, so no one who found him would strike him.'],
 "Lakhen (לָכֵן): 'therefore' or 'not so' (lo ken). The Hebrew reads 'therefore'; the LXX reads 'not so' (ouch houtōs): a witness variant, not a Hebrew reading. Shiv'atayim (שִׁבְעָתַיִם): 'seven-fold'. Ot (אוֹת): 'sign, mark'; its form is not described. LXX again has kyrios ho theos for YHWH, and reads ouch houtōs, 'not so', for lakhen."),
('4:16',
 ['Qayin went out from the face of the Lord and settled in the land of Nod—Wandering—east of Eden.'],
 "Nod (נוֹד): 'wandering', from nad (4:14); na' is a different root (4:12). LXX Naid, a transliteration that hides the pun."),
('4:17',
 ['Qayin knew his woman; she conceived and bore Chanokh.', 'He was building a city, and named the city after his son: Chanokh.'],
 "Bonneh ir (בֹּנֶה עִיר): 'building a city'. The first city in the text, named for a child. Chanokh (חֲנוֹךְ), 'dedicated, initiated'."),
('4:18',
 ['To Chanokh was born Irad;', 'Irad fathered Mechuyael;', 'Mechiyael fathered Methushael;', 'Methushael fathered Lamech.'],
 "Yillad (יִוָּלֵד): 'was born', passive. The Hebrew spells Mechuyael (4:18a) and Mechiyael (4:18b); the English keeps both spellings as given. Irad (עִירָד): unclear. Mechuyael (מְחוּיָאֵל): 'smitten by El' or 'given life by El'; contested. Methushael (מְתוּשָׁאֵל): 'man of El' or 'death of El' (mot); disputed. LXX Gaidad for Irad: the doubled 'Gaidad and Gaidad' renders the Hebrew's repeated 'and Irad fathered'; Maiel for Mechuyael; Mathousala for Methushael. The chain ends on Lamech, who takes two wives in 4:19. LXX reads 'Gaidad and Gaidad' (Γαιδαδ καὶ Γαιδαδ) and similar doubled names in the genealogy; recorded in the note at 4:18."),
]

# Apparatus: ambiguities and readings held open, per verse.
APP = {'1:1': ["re'shit: 'beginning' or 'head'. The construct allows 'at the beginning of' and the temporal reading 'when Divinity began'.", "bara': 'cut' is the chosen head term; the LXX has poiēsen, 'made'. The root is disputed."], '1:2': ["tohu wabohu: 'waste and emptiness'. A stammering pair, not two separate nouns.", "ruach: wind, breath, or spirit. 'Wind' is chosen; the other two stay open.", 'merachefet: fluttering, brooding. The bird over its young is Deut 32:11.'], '1:5': ["erev / boqer: evening and morning. Their verbal roots are uncertain. The formula is rendered 'came' in the English."], '1:6': ["raqia': a hammered sheet or the firmament. The root is 'to beat out'.", "lamayim: 'water to water' or 'to the waters'. Both readings are open."], '1:8': ["shamayim: heavens. The folk etymology sham-mayim, 'there are waters', is not established."], '1:9': ['qavah: gather and wait/hope are one root in the Hebrew, with two senses. Both senses are held as readings in the English.'], '1:14': ["mo'adim: appointed times or meeting-times, from ya'ad 'to meet'."], '1:16': ['mashal: rule and proverb are the same consonants. The English keeps the rule sense.'], '1:21': ['tanninim: sea-serpents or great monsters, the creature of older myth. Here it is made, not slain.'], '1:26': ["na'aseh, 'let us make': plural. Readings: a divine council, a royal we, or address to heavenly beings.", "tselem: image, shade, or shadow. The English keeps 'image'."], '2:4': ['toledot: births, generations, histories. The Greek title Genesis comes from the LXX rendering biblos geneseōs.'], '2:5': ['siach: bush or talk. Ps 77:13 uses the second sense.'], '2:7': ["afar: dust. appayim: nostrils, face, or anger. nefesh: throat, breath, soul, self. The LXX gives 'living soul'."], '2:8': ["Eden: delight, or a loanword from Sumerian edin 'steppe' (disputed).", "miqqedem: 'from the front', 'of old', or 'eastward'. The English keeps all three."], '2:9': ["da'at: knowing. yada' carries intimate knowledge (see 4:1).", "ra': harm, ruin, or evil. The English uses harm."], '2:17': ["be-yom: 'on the day', which may name an interval. mot tamut: 'dying you shall die'."], '2:18': ['ezer: help. Used of God in Ps 33:20. kenegdo: opposite him, or corresponding to him.'], '2:23': ["ish / ishah: man / woman. The pun is lost in English: 'woman, for from man'."], '2:24': ['davaq: cling, stick, cleave, the verb of joining.'], '3:1': ['arum: shrewd, crafty. Same consonants as arumim, naked (2:25). A deliberate pun in the Hebrew.', "nachash: serpent. Near nechoshet 'bronze' and nachash 'divination'."], '3:5': ["elohim in 'like elohim': divine beings, gods, or God. Plural in form."], '3:8': ['ruach ha-yom: wind of the day, or breeze of the day.'], '3:15': ["zera': seed, collective. hu: he or it; the referent is open. shuf: crush, bruise, or snap at. The English uses 'snap at' for both clauses."], '3:16': ["teshuqah: craving, drive, or pull. The same word is sin's craving at 4:7."], '3:19': ['appayim: nostrils, face, or anger.'], '3:20': ["Chavah: from chayah 'to live'. The text itself links them."], '3:22': ["mimmenu: 'of us' or 'of it'. The plural us is open."], '4:1': ["qaniti: I have gotten, or I have created. The 'et of 'et YHWH: with the Lord, or the Lord in apposition."], '4:2': ['Hevel: breath, vapour, vanity, ephemeral. See the names at the end of chapter 4.'], '4:7': ["se'et panim: lifting of the face, meaning acceptance or forgiveness. rovets: crouching, lying in wait. timshol: rule over."], '4:13': ["avon: guilt, twist, or punishment. nasa': carry, lift, or forgive. The English keeps both senses."], '4:15': ["lakhen: therefore, or not so (the LXX's reading)."], '4:16': ['Nod: wandering, from nad.'], '4:18': ['Mechuyael / Mechiyael: one name, written two ways in the Hebrew.']}

# Names: root meanings, given at the end of chapter 4. Uncertain ones are flagged.
NAMES = [("'adam", "the human; from adamah, red earth. The link is the text's own wordplay, not an established etymology."), ('chavah / Chavah', "Eve; from chayah, to live. The link is the text's wordplay; the form is anomalous."), ('Qayin', "spear or smith (a scholarly proposal); the text's own wordplay is qaniti, 'I have gotten'."), ('Hevel', 'breath, vapour, vanity, ephemeral; the word of Ecclesiastes. Hebel is the Hebrew for a bare breath.'), ('Eden', 'delight; or a loanword from Sumerian edin, steppe (disputed).'), ('Nod', 'wandering; from the root n-w-d, to wander or flee. Qayin is sent there.'), ('Chanokh', 'dedicated, initiated; from chanakh, to train or dedicate. Uncertain.'), ('Irad', 'unclear; perhaps wild ass, or a place name.'), ('Mechuyael', 'smitten by El, or given life by El; contested.'), ('Methushael', 'man of El, or death of El (mot); disputed.'), ('Lamech', 'unclear; possibly strong or powerful. Flagged as uncertain.'), ('Ishah / Ish', "woman / man. The pun is the text's own; ish and ishah are not established as one root. Kept in transliteration at 2:23."), ('Havilah', 'possibly from chul, to writhe or bring forth in labour; not established.'), ('Pishon / Gihon', 'Pishon unclear. Gihon is possibly from g-y-ch, to burst forth (a standard proposal, not settled).'), ('Hiddekel / Perat', 'Tigris and Euphrates.'), ('Kush / Ashur', 'southern land (Nubia or Ethiopia) and Assyria.')]
